      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-plugin-quota\",\n  \"version\": \"0.2.0\",\n  \"description\": \"实时用量仪表：会话级 token/轮次/估算花费实时追踪，注入系统提示 + /qm 面板 + quota_meter 卡片；也是家族通用插件开发测试模板（events/commands/tools/section/presentation 全覆盖）。\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./locale/*\": \"./locale/*\",\n    \"./icon.svg\": \"./icon.svg\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"locale\",\n    \"icon.svg\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"engines\": {\n    \"node\": \">=22.18\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.build.json\",\n    \"prepare\": \"npm run build\",\n    \"test\": \"node --test \\\"test/*.test.ts\\\"\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"check\": \"npm run typecheck && npm test && npm run build\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"cordis\",\n    \"plugin\",\n    \"quota\",\n    \"tokens\",\n    \"meter\",\n    \"realtime\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/121212165/dsh-plugin-quota.git\"\n  },\n  \"sideEffects\": false,\n  \"icon\": \"./icon.svg\",\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.2\",\n    \"@deepseek-ai/dsh-agent\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-base\": \"^0.1.2-alpha.4\",\n    \"@deepseek-ai/dsh-code-runtime\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-invariants\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-session-projection\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.2-alpha.4\",\n    \"@deepseek-ai/dsh-user-approval\": \"^0.1.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"3.18.2\",\n    \"@types/node\": \"26.6.2\",\n    \"typescript\": \"7.0.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.0\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/121212165/dsh-plugin-quota/issues\"\n  }\n}\n"
